import re

target_path = r"site-complete\info\contact.html"

with open(target_path, 'r', encoding='utf-8') as f:
    html = f.read()

# title & description
html = re.sub(r'<title>.*?</title>', '<title>お問い合わせ｜公益財団法人 全日本弓道連盟</title>', html)
html = re.sub(r'<meta name="description" content=".*?">', '<meta name="description" content="全日本弓道連盟へのお問い合わせ窓口、よくある質問、各種ご連絡先をご案内します。">', html)

new_main = '''<main class="wrap"><div class="crumb"><a href="../index.html">HOME</a><span>›</span>お問い合わせ</div><p class="eyebrow">ご案内</p><h1>お問い合わせ</h1><div class="meta"><span>公益財団法人 全日本弓道連盟</span></div><p class="summary">公益財団法人全日本弓道連盟公式ウェブサイトにお越しいただき、ありがとうございます。<br>大会や審査会に関するご質問や、取材・撮影のご相談、公式グッズ・書籍の購入、ご質問などを受け付けております。</p><section class="materials"><h2>お問い合わせ前にご確認ください</h2><p style="margin-bottom:1.5em;line-height:2">全日本弓道連盟では、弓道に関するよくある質問・疑問をまとめております。<br>「弓道ってどんな武道？」「弓道を始めるにはどうしたら良いの？」「会員ID・認許証の再交付について」など、お問い合わせの前にぜひご覧ください。</p><ul><li><a href="../begin/faq.html">よくある質問（FAQ）<span class="more" style="color:var(--sub);font-size:13px;margin-left:1em">詳しく見る</span></a></li></ul></section><section class="materials"><h2>お電話・ファックスでのお問い合わせ</h2><div style="background:rgba(255,255,255,.04);border:1px solid var(--line);border-radius:6px;padding:24px 28px;margin:1.5em 0;line-height:2"><p style="font-size:18px;font-weight:600;margin:0 0 .5em;letter-spacing:.1em">公益財団法人 全日本弓道連盟 事務局</p><p style="margin:.3em 0">FAX: 03-3481-2398</p><p style="margin:.3em 0;color:var(--sub);font-size:14px">受付時間：月～金 9:00～17:00（土・日・祝日、年末年始、夏季休暇などを除く）</p></div></section><section class="materials"><h2>お問い合わせフォーム</h2><p style="color:var(--sub);font-size:13px;margin-bottom:1.5em">※お返事を差し上げるまでにお時間がかかる場合があります。<br>※お問い合わせの内容によっては、お返事を差し上げられない場合があります。</p><form onsubmit="event.preventDefault();alert('ローカルミラー環境のため送信シミュレーションです。お問い合わせありがとうございました。');" style="display:flex;flex-direction:column;gap:18px;margin-top:1.5em"><div style="display:flex;flex-direction:column;gap:6px"><label style="font-size:14px;color:var(--sub)">お名前 <span style="color:#e06c75">（必須）</span></label><input type="text" required placeholder="例）弓道 太郎" style="background:rgba(255,255,255,.06);border:1px solid var(--line);color:var(--ink);padding:10px 14px;border-radius:4px;font-family:inherit"></div><div style="display:flex;flex-direction:column;gap:6px"><label style="font-size:14px;color:var(--sub)">ふりがな <span style="color:#e06c75">（必須）</span></label><input type="text" required placeholder="例）きゅうどう たろう" style="background:rgba(255,255,255,.06);border:1px solid var(--line);color:var(--ink);padding:10px 14px;border-radius:4px;font-family:inherit"></div><div style="display:flex;flex-direction:column;gap:6px"><label style="font-size:14px;color:var(--sub)">メールアドレス <span style="color:#e06c75">（必須）</span></label><input type="email" required placeholder="例）info@example.com" style="background:rgba(255,255,255,.06);border:1px solid var(--line);color:var(--ink);padding:10px 14px;border-radius:4px;font-family:inherit"></div><div style="display:flex;flex-direction:column;gap:6px"><label style="font-size:14px;color:var(--sub)">電話番号</label><input type="tel" placeholder="例）03-1234-5678" style="background:rgba(255,255,255,.06);border:1px solid var(--line);color:var(--ink);padding:10px 14px;border-radius:4px;font-family:inherit"></div><div style="display:flex;flex-direction:column;gap:6px"><label style="font-size:14px;color:var(--sub)">お問い合わせ内容 <span style="color:#e06c75">（必須）</span></label><textarea required rows="6" placeholder="お問い合わせ内容をご入力ください" style="background:rgba(255,255,255,.06);border:1px solid var(--line);color:var(--ink);padding:10px 14px;border-radius:4px;font-family:inherit;resize:vertical"></textarea></div><button type="submit" style="align-self:flex-start;background:var(--accent);color:#14121c;font-weight:600;padding:12px 32px;border-radius:4px;cursor:pointer;margin-top:10px;font-family:inherit;letter-spacing:.1em">送信する</button></form></section><p class="source"><a href="https://www.kyudo.jp/info/contact.html">公式サイトの掲載内容を確認する</a></p></main>'''

html = re.sub(r'<main class="wrap">.*?</main>', new_main, html, flags=re.DOTALL)

with open(target_path, 'w', encoding='utf-8') as f:
    f.write(html)

print("Updated info/contact.html successfully!")
